    f_best = func(x_best)

    T_initial = 1000
    alpha = 0.98
    T = T_initial

    for i in range(budget):
        candidate = clip(get_candidate(dim, lb, ub), lb, ub)
        f_candidate = func(candidate)

        if f_candidate < f_best:
